namespace sv_18a377e9942c4be8ba68a9f356e02cfd.Services;

public record Recipe(int Id, string Title, string Description, int PrepTimeMinutes);

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> _data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic pizza with fresh mozzarella and basil.", 25),
            new(2, "Pasta Carbonara", "Creamy egg-based pasta with pancetta.", 20),
            new(3, "Tiramisu", "Layered coffee-flavored Italian dessert.", 40),
        },
        [2] = new List<Recipe>
        {
            new(4, "Sushi Rolls", "Fresh fish and rice wrapped in nori.", 45),
            new(5, "Ramen", "Rich pork broth noodle soup with toppings.", 60),
            new(6, "Tempura", "Lightly battered and fried vegetables and shrimp.", 30),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple.", 35),
            new(8, "Guacamole", "Fresh avocado dip with lime and cilantro.", 10),
            new(9, "Enchiladas", "Rolled tortillas with sauce and cheese.", 50),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (_data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

